//#region src/main/agent/claudeRun.ts
/** Pulls assistant text out of one stream-json line. Mirrors handlers/agent.ts. */
function textFromLine(line) {
	const t = line.trim();
	if (!t || t[0] !== "{") return "";
	try {
		const obj = JSON.parse(t);
		if (obj.type === "stream_event" && obj.event?.type === "content_block_delta" && obj.event.delta?.type === "text_delta") return obj.event.delta.text ?? "";
		return "";
	} catch {
		return "";
	}
}
/** Pulls the final `result` text out of a stream-json line, if present. */
function resultText(line) {
	const t = line.trim();
	if (!t || t[0] !== "{") return null;
	try {
		const obj = JSON.parse(t);
		if (obj.type === "result" && !obj.is_error && typeof obj.result === "string") return obj.result;
		return null;
	} catch {
		return null;
	}
}
/**
* Runs `claude -p` once with the given prompt (via stdin) and system prompt,
* returning the assistant's full text. Streams deltas; falls back to the
* `result` event's text if no deltas arrived. `timeoutMs` guards against hangs.
*/
function runClaudeJson(opts) {
	const { prompt, systemPrompt, cwd, timeoutMs = 6e4, allowedTools = [] } = opts;
	const binary = resolveClaudeBinary();
	const args = [
		"--settings",
		"{\"disableAllHooks\":true}",
		"--output-format",
		"stream-json",
		"--include-partial-messages",
		"--verbose",
		...allowedTools.length ? ["--allowedTools", ...allowedTools] : [],
		...systemPrompt ? ["--append-system-prompt", systemPrompt] : [],
		"-p"
	];
	return new Promise((resolve) => {
		const child = spawn(binary, args, {
			cwd,
			stdio: [
				"pipe",
				"pipe",
				"pipe"
			]
		});
		let deltas = "";
		let finalResult = "";
		let buffer = "";
		let timedOut = false;
		const timer = setTimeout(() => {
			timedOut = true;
			child.kill("SIGTERM");
		}, timeoutMs);
		timer.unref?.();
		child.stdin?.on("error", () => {});
		child.stdin?.write(prompt);
		child.stdin?.end();
		const consume = (chunk) => {
			buffer += chunk;
			let nl;
			while ((nl = buffer.indexOf("\n")) !== -1) {
				const line = buffer.slice(0, nl);
				buffer = buffer.slice(nl + 1);
				deltas += textFromLine(line);
				const r = resultText(line);
				if (r !== null) finalResult = r;
			}
		};
		child.stdout?.on("data", (d) => consume(d.toString()));
		child.on("error", () => {});
		child.on("close", (code) => {
			clearTimeout(timer);
			if (buffer.trim()) {
				deltas += textFromLine(buffer);
				const r = resultText(buffer);
				if (r !== null) finalResult = r;
			}
			resolve({
				text: deltas.trim() ? deltas : finalResult,
				code,
				timedOut
			});
		});
	});
}
